window.ABSTRACTS = {
 "balogh-etal-typical-structure": {
  "source": "arXiv:1406.6961",
  "text": "In 1987, Kolaitis, Prömel and Rothschild proved that, for every fixed $r \\in \\mathbb{N}$, almost every $n$-vertex $K_{r+1}$-free graph is $r$-partite. In this paper we extend this result to all functions $r = r(n)$ with $r \\leqslant (\\log n)^{1/4}$. The proof combines a new (close to sharp) supersaturation version of the Erdős-Simonovits stability theorem, the hypergraph container method, and a counting technique developed by Balogh, Bollobás and Simonovits."
 },
 "bardenova-etal-wiener": {
  "source": "arXiv:2503.18920",
  "text": "The Wiener index of a vertex coloring of a graph is defined to be the sum of all pairwise geodesic distances between vertices of the same color. We provide characterizations of vertex colorings of paths and cycles whose Wiener index is as large as possible over various natural collections. Along the way we establish a connection between the majorization order on tuples of integers and the Wiener index of vertex colorings on paths and cycles."
 },
 "bednar-bushaw-rainbow-turan": {
  "source": "arXiv:2203.13765",
  "text": "The rainbow Turán number, a natural extension of the well studied traditional Turán number, was introduced in 2007 by Keevash, Mubayi, Sudakov and Verstraëte. The rainbow Turán number of a graph $H$, $ex^{*}(n,H)$, is the largest number of edges for an $n$ vertex graph $G$ which can be properly edge colored with no rainbow $H$ subgraph. We explore the reduction method for finding upper bounds on rainbow Turán numbers, and use this to inform results for the rainbow Turán numbers of double stars, caterpillars, and perfect binary trees. In addition, we define $k$-unique colorings and the related $k$-unique Turán numbers. We provide preliminary results on this new variant on the classic problem."
 },
 "bushaw-clifton-3nbr": {
  "source": "arXiv:2608.06133",
  "text": "In the $3$-neighbor bootstrap percolation process, a vertex becomes (and remains) infected if at least three of its neighbors are infected. We say that an initial configuration of infected vertices percolates if eventually all vertices are infected. We exactly determine the size of the minimum percolating set for the $3$-neighbor bootstrap percolation process on all remaining open cases for rectangular grid graphs $P_m\\square P_n$. This extends earlier work of Dukes, Noel, and Romer. Additionally, we consider the same question for the toroidal grids $C_m\\square C_n$, proving upper and lower bounds which are at most one apart and determining the answer precisely in many divisibility cases."
 },
 "bushaw-cody-leffler-energy": {
  "source": "arXiv:2407.18785",
  "text": "We define various notions of energy of a set of vertices in a graph, which generalize two of the most widely studied graphical indices: the Wiener index and the Harary index. We provide a new proof of a result due to Douthett and Krantz, which says that for cycles, the sets of vertices which have minimal energy among all sets of the same size are precisely the maximally even sets, as defined in Clough and Douthett's work on music theory. Generalizing a theorem of Clough and Douthett, we prove that a finite, simple, connected graph is distance degree regular if and only if whenever a set of vertices has minimal energy, its complement also has minimal energy. We also provide several characterizations of sets of vertices in finite paths and cycles for which the sum of all pairwise distances between vertices in the set is maximal among all sets of the same size."
 },
 "bushaw-cranston-tilings": {
  "source": "arXiv:1803.09056",
  "text": "In \\emph{$k$-bootstrap percolation}, we fix $p\\in (0,1)$, an integer $k$, and a plane graph $G$. Initially, we infect each face of $G$ independently with probability $p$. Infected faces remain infected forever, and if a healthy (uninfected) face has at least $k$ infected neighbors, then it becomes infected. For fixed $G$ and $p$, the \\emph{percolation threshold} is the largest $k$ such that eventually all faces become infected, with probability at least $1/2$. For a large class of infinite graphs, we show that this threshold is independent of $p$. We consider bootstrap percolation in tilings of the plane by regular polygons. A \\emph{vertex type} in such a tiling is the cyclic order of the faces that meet a common vertex. First, we determine the percolation threshold for each of the Archimedean lattices. More generally, let $\\mathcal{T}$ denote the set of plane tilings $T$ by regular polygons such that if $T$ contains one instance of a vertex type, then $T$ contains infinitely many instances of that type. We show that no tiling in $\\mathcal{T}$ has threshold 4 or more. Further, the only tilings in $\\mathcal{T}$ with threshold 3 are four of the Archimedean lattices. Finally, we describe a large subclass of $\\mathcal{T}$ with threshold 2."
 },
 "bushaw-czygrinow-yie-even-cycles": {
  "source": "arXiv:1806.09651",
  "text": "We will show that for $α>0$ there is $n_0$ such that if $G$ is a graph on $n\\geq n_0$ vertices such that $αn< δ(G)< (n-1)/2$, then for every $n_1+n_2+\\cdots +n_l= δ(G)$, $G$ contains a disjoint union of $C_{2n_1},C_{2n_2}, \\dots, C_{2n_l}$ unless $G$ has a very specific structure."
 },
 "bushaw-danielsson-hurlbert-ekr": {
  "source": "arXiv:2504.05406",
  "text": "A family of sets is $s$-intersecting if every pair of its sets has at least $s$ elements in common. It is an $s$-star if all its members have some $s$ elements in common. A family of sets is called $s$-EKR if all its $s$-intersecting subfamilies have size at most that of some $s$-star. For example, the classic 1961 Erdős-Ko-Rado theorem states essentially that the family of $r$-sized subsets of $\\{1,2,\\ldots,n\\}$ is $s$-EKR when $n$ is a large enough function of $r$ and $s$, and the 1967 Hilton-Milner theorem provides the near-star structure of the largest non-star intersecting family of such sets. Two important conjectures along these lines followed: by Chvátal in 1974, that every subset-closed family of sets is 1-EKR, and by Holroyd and Talbot in 2005, that, for every graph, the family of all its $r$-sized independent sets is 1-EKR when every maximal independent set has size at least $2r$. In this paper we present similar 1-EKR results for families of length-$r$ paths in graphs, specifically for sun graphs, which are cycles with pendant edges attached in a uniform way, and theta graphs, which are collections of pairwise internally disjoint paths sharing the same two endpoints. We also prove $s$-EKR results for such paths in suns, and give a Hilton-Milner type result for them as well. A set is a transversal of a family of sets if it intersects each member of the family, and the transversal number of the family is the size of its smallest transversal. For example, stars have transversal number 1, and the Hilton-Milner family has transversal number 2. We conclude the paper with some transversal results involving what we call triangular families, including a few results for projective planes."
 },
 "bushaw-etal-berge-stars": {
  "source": "arXiv:2502.17686",
  "text": "The forbidden subgraph problem is among the oldest in extremal combinatorics -- how many edges can an $n$-vertex $F$-free graph have? The answer to this question is the well-studied extremal number of $F$. Observing that every extremal example must be maximally $F$-free, a natural minimization problem is also studied -- how few edges can an $n$-vertex maximal $F$-free graph have? This leads to the saturation number of $F$. Both of these problems are notoriously difficult to extend to $k$-uniform hypergraphs for any $k\\ge 3$. Barefoot et al., in the case of forbidding triangles in graphs, asked a beautiful question -- which numbers of edges, between the saturation number and the extremal number, are actually realized by an $n$-vertex maximal $F$-free graph? Hence named the saturation spectrum of $F$, this has since been determined precisely for several classes of graphs through a large number of papers over the past two decades. In this paper, we extend the notion of the saturation spectrum to the hypergraph context. Given a graph $F$ and a hypergraph $G$ embedded on the same vertex set, we say $G$ is a {\\bf{Berge-$F$}} if there exists a bijection $φ:E(F)\\to E(G)$ such that $e\\subseteq φ(e)$ for all $e\\in E(F)$. We completely determine the saturation spectrum for $3$-uniform Berge-$K_{1,\\ell}$ for $1\\leq \\ell\\leq 4$, and for $\\ell=5$ when $5\\mid n$. We also determine all but a constant number of values in the spectrum for $3$-uniform Berge-$K_{1,\\ell}$ for all $\\ell\\geq 5$. We note that this is the first result determining the saturation spectrum for any non-trivial hypergraph."
 },
 "bushaw-etal-bridges-evenness": {
  "source": "arXiv:2407.18768",
  "text": "We use the concept of electric potential energy from physics, the mathematical field of graph theory, and the notion of majorization to study maximal evenness in a broader mathematical context than what was previously possible, so that we can go beyond the well-known one-dimensional maximally even sets into higher dimensional and more geometrically complex territory. We investigate musical connections between certain generalizations of maximally even sets, one of the oldest Puerto Rican musical traditions of African origin called bomba, and with certain scales ranging from the familiar to the esoteric."
 },
 "bushaw-etal-large-matchings": {
  "source": "arXiv:1209.2033",
  "text": "Let $K_{n}^{r}$ denote the complete $r$-uniform hypergraph on $n$ vertices. A matching $M$ in a hypergraph is a set of pairwise vertex disjoint edges. Recent Ramsey-type results rely on lemmas about the size of monochromatic matchings. A starting point for this study comes from a well-known result of Alon, Frankl, and Lovász (1986). Our motivation is to find the smallest $n$ such that every $t$-coloring of $K_{n}^{r}$ contains an $s$-colored matching of size $k$. It has been conjectured that in every coloring of the edges of $K_n^r$ with 3 colors there is a 2-colored matching of size at least $k$ provided that $n \\geq kr + \\lfloor \\frac{k-1}{r+1} \\rfloor$. The smallest test case is when $r=3$ and $k=4$. We prove that in every 3-coloring of the edges of $K_{12}^3$ there is a 2-colored matching of size 4."
 },
 "bushaw-etal-sumfree": {
  "source": "arXiv:1310.3236",
  "text": "We study sum-free sets in sparse random subsets of even order abelian groups. In particular, we determine the sharp threshold for the following property: the largest such set is contained in some maximum-size sum-free subset of the group. This theorem extends recent work of Balogh, Morris and Samotij, who resolved the case G = Z_{2n}, and who obtained a weaker threshold (up to a constant factor) in general."
 },
 "bushaw-gunderson-kalikow-markov": {
  "source": "arXiv:1410.1457",
  "text": "We explore two notions of stationary processes. The first is called a random-step Markov process in which the stationary process of states, $(X_i)_{i \\in \\mathbb{Z}}$ has a stationary coupling with an independent process on the positive integers, $(L_i)_{i \\in \\mathbb{Z}}$ of `random look-back distances'. That is, $L_0$ is independent of the `past states', $(X_i, L_i)_{i<0}$, and for every positive integer $n$, the probability distribution on the `present', $X_0$, conditioned on the event $\\{L_0 = n\\}$ and on the past is the same as the probability distribution on $X_0$ conditioned on the `$n$-past', $(X_i)_{-n\\leq i <0}$ and $\\{L_0 = n\\}$. A random Markov process is a generalization of a Markov chain of order $n$ and has the property that the distribution on the present given the past can be uniformly approximated given the $n$-past, for $n$ sufficiently large. Processes with the latter property are called uniform martingales, closely related to the notion of a `continuous $g$-function'. We show that every stationary process on a countable alphabet that is a uniform martingale and is dominated by a finite measure is also a random Markov process and that the random variables $(L_i)_{i \\in \\mathbb{Z}}$ and associated coupling can be chosen so that the distribution on the present given the $n$-past and the event $\\{L_0 = n\\}$ is `deterministic': all probabilities are in $\\{0,1\\}$. In the case of finite alphabets, those random-step Markov processes for which $L_0$ can be chosen with finite expected value are characterized. For stationary processes on an uncountable alphabet, a stronger condition is also considered which is sufficient to imply that a process is a random Markov processes. In addition, a number of examples are given throughout to show the sharpness of the results."
 },
 "bushaw-hurlbert-crossnumber": {
  "source": "arXiv:2309.03455",
  "text": "For an additive group $Γ$ the sequence $S = (g_1, \\ldots, g_t)$ of elements of $Γ$ is a zero-sum sequence if $g_1 + \\cdots + g_t = 0_Γ$. The cross number of $S$ is defined to be the sum $\\sum_{i=1}^k 1/|g_i|$, where $|g_i|$ denotes the order of $g_i$ in $Γ$. Call $S$ good if it contains a zero-sum subsequence with cross number at most 1. In 1993, Geroldinger proved that if $Γ$ is abelian then every length $|Γ|$ sequence of its elements is good, generalizing a 1989 result of Lemke and Kleitman that had proved an earlier conjecture of Erdős and Lemke. In 1989 Chung re-proved the Lemke and Kleitman result by applying a theorem of graph pebbling, and in 2005, Elledge and Hurlbert used graph pebbling to re-prove and generalize Geroldinger's result. Here we use probabilistic theorems from graph pebbling to derive a threshold version of Geroldinger's theorem for abelian groups of a certain form. Specifically, we prove that if $p_1, \\ldots, p_d$ are (not necessarily distinct) primes and $Γ_k$ has the form $\\prod_{i=1}^d {\\mathbb Z}_{p_i^k}$ then there is a function $τ=τ(k)$ (which we specify in Theorem 4) with the following property: if $t-τ\\rightarrow\\infty$ as $k\\rightarrow\\infty$ then the probability that $S$ is good in $Γ_k$ tends to 1."
 },
 "bushaw-johnston-rombach-rainbow-sat": {
  "source": "arXiv:2003.13200",
  "text": "We introduce a notion of rainbow saturation and the corresponding rainbow saturation number. This is the saturation version of the rainbow Turán numbers whose systematic study was initiated by Keevash, Mubayi, Sudakov, and Verstraëte. We give examples of graphs for which the rainbow saturation number is bounded away from the ordinary saturation number. This includes all complete graphs $K_n$ for $n\\geq 4$, and several bipartite graphs. It is notable that there are non-bipartite graphs for which this is the case, as this does not happen when it comes to the rainbow extremal number versus the traditional extremal number. We also show that saturation numbers are linear for a large class of graphs, providing a partial rainbow analogue of a well known theorem of Kásonyi and Tuza. We conclude this paper with related open questions and conjectures."
 },
 "bushaw-kettle-hypergraph-paths": {
  "source": "arXiv:1303.5022",
  "text": "The Turán number of an r-uniform hypergraph H is the maximum number of edges in any r-graph on n vertices which does not contain H as a subgraph. Let P_l^(r) denote the family of r-uniform loose paths on l edges, F(k,l) denote the family of hypergraphs consisting of k disjoint paths from P_l^(r), and P'_l^(r) denote an r-uniform linear path on l edges. We determine precisely ex_r(n;F(k,l)) and ex_r(n;k*P'_l^(r)), as well as the Turán numbers for forests of paths of differing lengths (whether these paths are loose or linear) when n is appropriately large dependent on k,l,r, for r>=3. Our results build on recent results of Füredi, Jiang, and Seiver who determined the extremal numbers for individual paths, and provide more hypergraphs whose Turan numbers are exactly determined."
 },
 "bushaw-kettle-multiple-paths": {
  "source": "arXiv:1106.5904",
  "text": "The Turán number of a graph H, ex(n;H), is the maximum number of edges in any graph on n vertices which does not contain H as a subgraph. Let P_l denote a path on l vertices, and kP_l denote k vertex-disjoint copies of P_l. We determine ex(n, kP_3) for n appropriately large, answering in the positive a conjecture of Gorgol. Further, we determine ex (n, kP_l) for arbitrary l, and n appropriately large relative to k and l. We provide some background on the famous Erdős-Sós conjecture, and conditional on its truth we determine ex(n;H) when H is an equibipartite forest, for appropriately large n."
 },
 "bushaw-kettle-pebbling": {
  "source": "arXiv:2309.01762",
  "text": "Given a connected graph $G$ and a configuration of $t$ pebbles on the vertices of G, a $q$-pebbling step consists of removing $q$ pebbles from a vertex, and adding a single pebble to one of its neighbors. Given a vector $\\bf{q}=(q_1,\\ldots,q_d)$, $\\bf{q}$-pebbling consists of allowing $q_i$-pebbling in coordinate $i$. A distribution of pebbles is called solvable if it is possible to transfer at least one pebble to any specified vertex of $G$ via a finite sequence of pebbling steps. In this paper, we determine the weak threshold for $\\bf{q}$-pebbling on the sequence of grids $[n]^d$ for fixed $d$ and $\\bf{q}$, as $n\\to\\infty$. Further, we determine the strong threshold for $q$-pebbling on the sequence of paths of increasing length. A fundamental tool in these proofs is a new notion of centrality, and a sufficient condition for solvability based on the well used pebbling weight functions; we believe this weight lemma to be the first result of its kind, and may be of independent interest. These theorems improve recent results of Czygrinow and Hurlbert, and Godbole, Jablonski, Salzman, and Wierman. They are the generalizations to the random setting of much earlier results of Chung. In addition, we give a short counterexample showing that the threshold version of a well known conjecture of Graham does not hold. This uses a result for hypercubes due to Czygrinow and Wagner."
 },
 "bushaw-larson-vancleemput-acvii": {
  "source": "arXiv:1801.01814",
  "text": "The Graph Brain Project is an experiment in how the use of automated mathematical discovery software, databases, large collaboration, and systematic investigation provide a model for how mathematical research might proceed in the future. Our Project began with the development of a program that can be used to generate invariant-relation and property-relation conjectures in many areas of mathematics. This program can produce conjectures which are not implied by existing (published) theorems. Here we propose a new approach to push forward existing mathematical research goals---using automated mathematical discovery software. We suggest how to initiate and harness large-scale collaborative mathematics. We envision mathematical research labs similar to what exist in other sciences, new avenues for funding, new opportunities for training students, and a more efficient and effective use of published mathematical research. And our experiment in graph theory can be imitated in many other areas of mathematical research. Big Mathematics is the idea of large, systematic, collaborative research on problems of existing mathematical interest. What is possible when we put our skills, tools, and results together systematically?"
 }
};
